/* 학습 해설
 * Llist·CAS 기반 연결과 소비자 규약
 * 짧은 지연 작업 목록을 여러 CPU에서 추가할 때 공유 mutex 없이 연결을 갱신하는 규약이 쓰입니다.
 * Llist add는 새 목록의 끝을 기존 head에 붙이고 cmpxchg로 head를 교환합니다. 경쟁으로 head가 바뀌면 다시 시도합니다. Lockless라는 이름은 임의 다중 소비자·해제를 항상 허용한다는 뜻이 아니며 del_first와 del_all의 동시성 조건을 구분합니다.
 * llist_add·add_batch와 적합한 소비 방식의 문서를 따릅니다. 소비한 객체의 수명·재사용·ABA 위험을 관리합니다. v6.12 주석의 del_first는 다중 소비자에 별도 lock이 필요하다는 제약을 확인합니다.
 */
bool llist_add_batch(struct llist_node *new_first, struct llist_node *new_last,
		     struct llist_head *head)
{
	struct llist_node *first = READ_ONCE(head->first);

	do {
		new_last->next = first;
	} while (!try_cmpxchg(&head->first, &first, new_first));

	return !first;
}
EXPORT_SYMBOL_GPL(llist_add_batch);

/**
 * llist_del_first - delete the first entry of lock-less list
 * @head:	the head for your lock-less list
 *
 * If list is empty, return NULL, otherwise, return the first entry
 * deleted, this is the newest added one.
 *
 * Only one llist_del_first user can be used simultaneously with
 * multiple llist_add users without lock.  Because otherwise
 * llist_del_first, llist_add, llist_add (or llist_del_all, llist_add,
 * llist_add) sequence in another user may change @head->first->next,
 * but keep @head->first.  If multiple consumers are needed, please
 * use llist_del_all or use lock between consumers.
 */

/* 학습 해설
 * Sbitmap·분산 비트맵과 대기 큐
 * 높은 동시성의 tag 할당에서 한 비트맵 word와 하나의 대기 큐에 경쟁이 집중될 수 있습니다.
 * Sbitmap은 bit를 여러 word에 나누고 CPU별 allocation hint 등으로 검색을 분산합니다. Sbitmap queue는 가용 bit가 없을 때 대기와 해제 후 wake를 연결합니다. Shallow depth는 특정 요청이 각 word의 일부만 사용하도록 제한하며 전체 tag 수를 무조건 줄이는 것과 다릅니다.
 * init·get·clear·wake·free 수명을 따릅니다. 반환 음수는 할당 실패로 처리하고 bit 해제와 대기자 깨움 순서를 확인합니다. blk-mq tag의 실제 사용과 이 library의 bit 소유를 연결합니다.
 */
int sbitmap_get(struct sbitmap *sb)
{
	int nr;
	unsigned int hint, depth;

	if (WARN_ON_ONCE(unlikely(!sb->alloc_hint)))
		return -1;

	depth = READ_ONCE(sb->depth);
	hint = update_alloc_hint_before_get(sb, depth);
	nr = __sbitmap_get(sb, hint);
	update_alloc_hint_after_get(sb, depth, hint, nr);

	return nr;
}
EXPORT_SYMBOL_GPL(sbitmap_get);

static int __sbitmap_get_shallow(struct sbitmap *sb,
				 unsigned int alloc_hint,
				 unsigned long shallow_depth)
{
	unsigned int index;

	index = SB_NR_TO_INDEX(sb, alloc_hint);
	alloc_hint = SB_NR_TO_BIT(sb, alloc_hint);

/* 학습 해설
 * PerCPU Refcount·분산 참조의 종료 전환
 * 매 I/O마다 하나의 refcount cache line을 갱신하면 경쟁이 커져 지역 참조와 안전한 종료가 필요합니다.
 * PerCPU ref는 정상 실행의 CPU별 참조 갱신과 종료를 위한 atomic 모드를 전환합니다. 전환은 기존 CPU별 접근이 지나가도록 조정한 뒤 합계를 반영합니다. Switch 호출 반환과 confirm 완료, kill과 마지막 release는 서로 다른 단계입니다.
 * init·get/put·kill·confirm·release·exit의 규약을 따릅니다. 종료 시 새 참조가 생기는 경계를 막고 기존 참조가 끝날 때 객체를 해제합니다. 전환 중 임의 모드 변경이나 빠른 ref 직접 읽기를 하지 않습니다.
 */
void percpu_ref_switch_to_atomic(struct percpu_ref *ref,
				 percpu_ref_func_t *confirm_switch)
{
	unsigned long flags;

	spin_lock_irqsave(&percpu_ref_switch_lock, flags);

	ref->data->force_atomic = true;
	__percpu_ref_switch_mode(ref, confirm_switch);

	spin_unlock_irqrestore(&percpu_ref_switch_lock, flags);
}
EXPORT_SYMBOL_GPL(percpu_ref_switch_to_atomic);

/**
 * percpu_ref_switch_to_atomic_sync - switch a percpu_ref to atomic mode
 * @ref: percpu_ref to switch to atomic mode
 *
 * Schedule switching the ref to atomic mode, and wait for the
 * switch to complete.  Caller must ensure that no other thread
 * will switch back to percpu mode.
 */
void percpu_ref_switch_to_atomic_sync(struct percpu_ref *ref)
{
	percpu_ref_switch_to_atomic(ref, NULL);
	wait_event(percpu_ref_switch_waitq, !ref->data->confirm_switch);

/* 학습 해설
 * Stack Depot·중복 스택과 Handle
 * 많은 객체의 할당 stack을 그대로 저장하면 반복된 주소열이 큰 메모리를 쓰므로 중복을 줄일 수 있습니다.
 * Stack depot은 stack 주소열을 해시해 bucket에서 실제 entries를 비교하고 동일 기록을 공유 handle로 참조합니다. 저장 공간 pool과 handle 인코딩·참조 수명·할당 flags를 관리합니다. Hash가 같다는 것만으로 다른 stack을 합치지 않습니다.
 * stack_depot_save_flags와 fetch·put 지원 규약을 따릅니다. Context의 GFP·할당 허용·실패 handle을 확인하고 handle 수명 동안 해당 기록이 유지되는지 검토합니다. Interrupt stack 필터가 중복률에 영향을 줍니다.
 */
depot_stack_handle_t stack_depot_save_flags(unsigned long *entries,
					    unsigned int nr_entries,
					    gfp_t alloc_flags,
					    depot_flags_t depot_flags)
{
	struct list_head *bucket;
	struct stack_record *found = NULL;
	depot_stack_handle_t handle = 0;
	struct page *page = NULL;
	void *prealloc = NULL;
	bool can_alloc = depot_flags & STACK_DEPOT_FLAG_CAN_ALLOC;
	unsigned long flags;
	u32 hash;

	if (WARN_ON(depot_flags & ~STACK_DEPOT_FLAGS_MASK))
		return 0;

	/*
	 * If this stack trace is from an interrupt, including anything before
	 * interrupt entry usually leads to unbounded stack depot growth.
	 *
	 * Since use of filter_irq_stacks() is a requirement to ensure stack
	 * depot can efficiently deduplicate interrupt stacks, always
	 * filter_irq_stacks() to simplify all callers' use of stack depot.
	 */
	nr_entries = filter_irq_stacks(entries, nr_entries);

/* 학습 해설
 * HMAC·내부·외부 키 패드
 * 메시지 인증에는 비밀 키를 포함한 정해진 해시 구성이 필요하며 단순 접두사 해시와 구분해야 합니다.
 * HMAC은 H((K0 XOR opad)||H((K0 XOR ipad)||M))을 계산합니다. K0는 block size에 맞게 정규화한 키이며 긴 키는 먼저 hash하고 짧은 부분은 0으로 채웁니다. 내부·외부 패드 상수는 0x36·0x5c입니다. Linux는 패드까지 처리한 hash 상태를 export해 반복 작업을 줄입니다.
 * hmac(sha256) 같은 지원 Crypto API를 사용하고 키·tag 길이·검증 규약을 따릅니다. 메시지를 숨기는 암호화와 MAC의 변조 검출을 구분합니다. raw hash에 임의로 키를 붙여 대체하지 않습니다.
 */
static int hmac_setkey(struct crypto_shash *parent,
		       const u8 *inkey, unsigned int keylen)
{
	int bs = crypto_shash_blocksize(parent);
	int ds = crypto_shash_digestsize(parent);
	int ss = crypto_shash_statesize(parent);
	struct hmac_ctx *tctx = crypto_shash_ctx(parent);
	struct crypto_shash *hash = tctx->hash;
	u8 *ipad = &tctx->pads[0];
	u8 *opad = &tctx->pads[ss];
	SHASH_DESC_ON_STACK(shash, hash);
	unsigned int i;

	if (fips_enabled && (keylen < 112 / 8))
		return -EINVAL;

	shash->tfm = hash;

	if (keylen > bs) {
		int err;

		err = crypto_shash_digest(shash, inkey, keylen, ipad);
		if (err)
			return err;

		keylen = ds;

/* 학습 해설
 * CMAC·블록 암호 기반 인증
 * 고정 길이 블록 암호를 임의 길이 메시지의 인증값 계산에 사용하려면 마지막 블록 처리 규약이 필요합니다.
 * CMAC은 CBC 형태로 누적하며 E_K(0)에서 유한체 두 배 연산으로 subkey K1·K2를 만듭니다. 마지막 블록이 완전하면 K1, 불완전하면 1 bit와 0 padding 후 K2를 XOR해 암호화합니다. 키가 필요한 MAC이며 내용 암호화 모드와 다릅니다.
 * cmac(aes) 등의 검토된 API를 사용하고 빈 메시지·완전 마지막 블록·부분 마지막 블록을 구분해 시험합니다. 임의 CBC 결과 마지막 블록을 그대로 MAC으로 삼지 않습니다.
 */
static int crypto_cmac_digest_final(struct shash_desc *pdesc, u8 *out)
{
	struct crypto_shash *parent = pdesc->tfm;
	struct cmac_tfm_ctx *tctx = crypto_shash_ctx(parent);
	struct cmac_desc_ctx *ctx = shash_desc_ctx(pdesc);
	struct crypto_cipher *tfm = tctx->child;
	int bs = crypto_shash_blocksize(parent);
	u8 *odds = ctx->odds;
	u8 *prev = odds + bs;
	unsigned int offset = 0;

	if (ctx->len != bs) {
		unsigned int rlen;
		u8 *p = odds + ctx->len;

		*p = 0x80;
		p++;

		rlen = bs - ctx->len - 1;
		if (rlen)
			memset(p, 0, rlen);

		offset += bs;
	}

	crypto_xor(prev, odds, bs);

/* 학습 해설
 * CBC·이전 암호문과 XOR 연결
 * 여러 블록을 암호화할 때 이전 암호문을 다음 블록 계산에 넣는 연결 방식을 이해해야 합니다.
 * CBC 암호화는 C_i=E_K(P_i XOR C_(i-1))이며 C_0은 IV입니다. 복호화는 P_i=D_K(C_i) XOR C_(i-1)입니다. Padding·IV의 안전 규약·인증은 별도이며 raw kernel CBC는 임의 메시지 길이의 padding을 자동 정의하지 않습니다.
 * 프로토콜이 정한 IV·padding·MAC 규약을 따릅니다. 암호문만으로 인증이 생기지 않으며 복호화 오류가 padding oracle로 드러나지 않도록 설계합니다. 새 구성을 임의로 만들지 않습니다.
 */
static int crypto_cbc_encrypt_segment(struct crypto_lskcipher *tfm,
				      const u8 *src, u8 *dst, unsigned nbytes,
				      u8 *iv)
{
	unsigned int bsize = crypto_lskcipher_blocksize(tfm);

	for (; nbytes >= bsize; src += bsize, dst += bsize, nbytes -= bsize) {
		crypto_xor(iv, src, bsize);
		crypto_lskcipher_encrypt(tfm, iv, dst, bsize, NULL);
		memcpy(iv, dst, bsize);
	}

	return nbytes;
}

static int crypto_cbc_encrypt_inplace(struct crypto_lskcipher *tfm,
				      u8 *src, unsigned nbytes, u8 *oiv)
{
	unsigned int bsize = crypto_lskcipher_blocksize(tfm);
	u8 *iv = oiv;

	if (nbytes < bsize)
		goto out;

	do {
		crypto_xor(src, iv, bsize);

/* 학습 해설
 * CTR·카운터 암호와 XOR
 * 블록 암호로 키스트림을 만들면 마지막 부분 블록까지 XOR로 처리할 수 있지만 중복 관리가 필요합니다.
 * CTR은 S_i=E_K(counter_i)를 만들고 C_i=P_i XOR S_i로 처리합니다. 복호화도 같은 XOR입니다. Counter는 정해진 배치와 증가 규약을 따르며 같은 키 아래 counter block이 반복되면 keystream이 재사용됩니다. 인증은 별도입니다.
 * 전체 nonce·counter 공간과 증가·넘침·메시지 간 중복을 관리합니다. 구현의 IV 갱신 규약을 확인하고 검토된 인증 구성을 함께 사용합니다. Partial tail은 keystream 필요한 바이트만 XOR합니다.
 */
static int crypto_ctr_crypt_segment(struct skcipher_walk *walk,
				    struct crypto_cipher *tfm)
{
	void (*fn)(struct crypto_tfm *, u8 *, const u8 *) =
		   crypto_cipher_alg(tfm)->cia_encrypt;
	unsigned int bsize = crypto_cipher_blocksize(tfm);
	u8 *ctrblk = walk->iv;
	u8 *src = walk->src.virt.addr;
	u8 *dst = walk->dst.virt.addr;
	unsigned int nbytes = walk->nbytes;

	do {
		/* create keystream */
		fn(crypto_cipher_tfm(tfm), dst, ctrblk);
		crypto_xor(dst, src, bsize);

		/* increment counter in counterblock */
		crypto_inc(ctrblk, bsize);

		src += bsize;
		dst += bsize;
	} while ((nbytes -= bsize) >= bsize);

	return nbytes;
}

/* 학습 해설
 * ECB·블록 독립과 패턴 노출
 * 소스에 있는 단순 암호 모드의 동작과 보안 한계를 알아야 잘못된 적용을 피할 수 있습니다.
 * ECB는 각 완전 블록 C_i=E_K(P_i)를 독립 계산합니다. 같은 키에서 같은 평문 블록은 같은 암호문 블록이 되어 반복 패턴이 드러납니다. IV·블록 간 연결·인증을 제공하지 않으며 generic wrapper는 불완전 final 길이를 거부합니다.
